Get-ChildItem -Path 'c:\Codeverse\public', 'c:\Codeverse\' -Include *.html,*.js,*.css,*.md -Recurse -File | ForEach-Object { $content = Get-Content $_.FullName -Raw; $newContent = $content -replace 'CodeVerse 2026', 'CodeVerse 2.0' -replace 'CODEVERSE 2026', 'CODEVERSE 2.0'; if ($content -cne $newContent) { Set-Content -Path $_.FullName -Value $newContent -NoNewline; Write-Host "Updated $($_.FullName)" } }
